bool Lock::tryLockWithTimeout(Seconds timeout)
{
#if OS(DIHOS)
    // There is no signal-handler ABI in this profile. Native sleep yields
    // the EL0 thread; never invoke a POSIX call or busy-wait in the kernel.
    if (tryLock())
        return true;
    if (!(timeout > Seconds(0)))
        return false; // Includes NaN, negative and zero timeouts.
    auto deadline = MonotonicTime::now() + timeout;
    do {
        if (sacx_user_call(SACX_USER_SLEEP_MS, 1, 0, 0))
            __builtin_trap();
        if (tryLock())
            return true;
    } while (MonotonicTime::now() < deadline);
    return false;
#else

